        MAX(CASE WHEN level='region' THEN wholesale_pp_profit_sum END) AS wholesale_pp_profit_region_total,
        MAX(CASE WHEN level='sub_region' THEN wholesale_pp_profit_sum END) AS wholesale_pp_profit_sub_region_total,
